def wrap(text: str, width: int = 72) -> list[str]:
    """按词折行，避免一行太长压到页边。"""
    lines, cur = [], ""
    for word in text.split():
        if len(cur) + len(word) + 1 <= width:
            cur = f"{cur} {word}".strip()
        else:
            lines.append(cur)
            cur = word
    if cur:
        lines.append(cur)
    return lines


